CREATE PROCEDURE sp_InsertEmployee
    @FirstName NVARCHAR(50),
    @LastName NVARCHAR(50),
    @Department NVARCHAR(50),
    @Salary DECIMAL(10,2)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        INSERT INTO Employees (FirstName, LastName, Department, Salary)
        VALUES (@FirstName, @LastName, @Department, @Salary);

        SELECT
            SCOPE_IDENTITY() AS NewEmployeeID,
            'Employee created successfully.' AS Message;
    END TRY
    BEGIN CATCH
        DECLARE @ErrNum INT = ERROR_NUMBER();
        DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrSev INT = ERROR_SEVERITY();
        DECLARE @ErrState INT = ERROR_STATE();

        -- Log the error
        INSERT INTO ErrorLog (ErrorNumber, ErrorMessage, ErrorSeverity, ErrorState, ErrorTime)
        VALUES (@ErrNum, @ErrMsg, @ErrSev, @ErrState, GETDATE());

        -- Return a user-friendly message
        THROW @ErrNum, 'Failed to create employee: ' + @ErrMsg, @ErrState;
    END CATCH
END;
